package com.example.leavemanagement.integration;
import com.example.leavemanagement.request.domain.*;import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.SpringBootTest;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest class AdministrationWorkflowTest extends PostgresIntegrationTest { @Test void configuredWeeklyOffAndHolidayChangeChargeableWorkflow(){var calculator=new LeaveDurationCalculator();var result=calculator.calculate(LocalDate.of(2026,8,20),LocalDate.of(2026,8,23),DurationMode.FULL_DAY,true,true,Set.of(6,7),true,Set.of(LocalDate.of(2026,8,20)));assertThat(result.chargeableDates()).containsExactly(LocalDate.of(2026,8,21));assertThat(result.excludedDates()).extracting(LeaveCalculation.ExcludedDate::reason).containsExactly(LeaveCalculation.ExclusionReason.HOLIDAY,LeaveCalculation.ExclusionReason.WEEKLY_OFF,LeaveCalculation.ExclusionReason.WEEKLY_OFF);}
 @Test void configuredHalfDayRuleIsApplied(){var calculator=new LeaveDurationCalculator();assertThat(calculator.calculate(LocalDate.of(2026,8,21),LocalDate.of(2026,8,21),DurationMode.HALF_DAY_AM,true,false,Set.of(),false,Set.of()).chargeableUnits().days()).isEqualTo(0.5);}
}
